CmdResult handleUnregisteredClientAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCapabilities()) {
        return CMD_FAILURE;
    }

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = std::make_unique<SASLAuthenticator>(user);
    }

    if (!user->saslAuthenticator->sendClientMessage(parameters)) {
        user->sendNumeric(ERR_SASLFAIL, "SASL authentication failed");
        user->saslAuthenticator.reset();
        return CMD_FAILURE;
    }

    return CMD_SUCCESS;
}

CmdResult handleUnregisteredClientAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCap("sasl")) {
        return CMD_FAILURE;
    }

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = std::make_unique<SASLAuthenticator>(parameters);
    }

    if (!user->saslAuthenticator->sendClientMessage()) {
        user->saslAuthenticator = nullptr;
        return CMD_FAILURE;
    }

    return CMD_SUCCESS;
}

CmdResult handleUnregisteredClientAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCapabilities("sasl")) {
        return CMD_FAILURE;
    }

    if (!user->getSASLAuthenticator()) {
        user->setSASLAuthenticator(std::make_unique<SASLAuthenticator>(parameters));
    }

    if (!user->getSASLAuthenticator()->sendClientMessage(user)) {
        user->announce("AUTHENTICATOR-FAILED");
        user->unsetSASLAuthenticator();
        return CMD_FAILURE;
    }

    return CMD_FAILURE;
}

CmdResult handleUnregisteredClientAuthSASL(const std::vector<std::string>& parameters, User* user) {
    if (!user->isUnregistered())
        return CMD_RESULT_FAILURE;

    if (!user->hasCap("sasl"))
        return CMD_RESULT_FAILURE;

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = new SASLAuthenticator(user);
    }

    if (!user->saslAuthenticator->sendClientMessage(parameters)) {
        user->saslAuthenticator->announceState();
        delete user->saslAuthenticator;
        user->saslAuthenticator = nullptr;
        return CMD_RESULT_FAILURE;
    }

    return CMD_RESULT_SUCCESS;
}

CmdResult handleUnregisteredSaslAuth(const std::vector<std::string>& parameters, User* user) {
    if (user->isRegistered()) {
        return CMD_FAILURE;
    }

    if (!user->hasCapabilities("sasl")) {
        user->write("CAP * ACK :sasl");
    }

    if (!user->saslAuthenticator) {
        user->saslAuthenticator = std::make_unique<SaslAuthenticator>(user);
    }

    if (!user->saslAuthenticator->sendClientMessage(parameters)) {
        user->write("AUTHENTICATE +");
        user->saslAuthenticator.reset();
        return CMD_FAILURE;
    }

    return CMD_SUCCESS;
}
